INSERT [dbo].[AnnouncementsEntry] ([uuid_], [entryId], [companyId], [userId], [userName], [createDate], [modifiedDate], [classNameId], [classPK], [title], [content], [url], [type_], [displayDate], [expirationDate], [priority], [alert]) VALUES (N'490f3cac-88bd-21eb-33a4-0384c067ff07', 415890, 20102, 320298, N'Michael Heinrich', CAST(N'2021-10-19T18:37:27.0560000' AS DateTime2), CAST(N'2021-10-19T18:38:49.0020000' AS DateTime2), 20001, 292005, N'Did you know?', N'<p>You can invite additional users to your Church Mutual portal account.
  Account Owners and Members with appropriate permissions can manage
  users in the Profile area. Click here to check it out!</p>', N'https://test-portal.churchmutual.com/group/producer/profile', N'general', CAST(N'2021-10-19T18:37:00.0000000' AS DateTime2), CAST(N'2021-11-19T18:36:00.0000000' AS DateTime2), 0, 0)
GO
INSERT [dbo].[AnnouncementsEntry] ([uuid_], [entryId], [companyId], [userId], [userName], [createDate], [modifiedDate], [classNameId], [classPK], [title], [content], [url], [type_], [displayDate], [expirationDate], [priority], [alert]) VALUES (N'8337fdb5-13b2-1703-f26e-c446ae88770e', 445068, 20102, 320298, N'Michael Heinrich', CAST(N'2021-12-08T16:01:28.1730000' AS DateTime2), CAST(N'2021-12-08T16:01:28.1730000' AS DateTime2), 20001, 292005, N'Happy Holidays from Church Mutual', N'<p style="text-align: left;">
  <span style="">
    <span style="unicode-bidi: embed;">
      <span style="">
        <span style="">
          <span style="font-size: 20.0pt;">
            <span style="font-family: &quot;Script MT Bold&quot;;">
              <span style="color: black;">
                <span style="">As the holiday season is upon us, we find
                  ourselves reflecting on the past year and on those who
                  have helped us shape our business. We value our
                  relationship with you and look forward to working with
                  you in the year to come.</span></span></span></span></span></span></span></span></p>
<p style="text-align: left;">
  <span style="">
    <span style="unicode-bidi: embed;">
      <span style="">
        <span style="">
          <span style="font-size: 20.0pt;">
            <span style="font-family: &quot;Script MT Bold&quot;;">
              <span style="color: black;">
                <span style="">We wish you a happy holiday season and a
                  New Year filled with peace and prosperity!</span></span></span></span></span></span></span></span></p>
<p style="text-align: left;">
  <span style="">
    <span style="unicode-bidi: embed;">
      <span style="">
        <span style="">
          <span style="font-size: 20.0pt;">
            <span style="font-family: &quot;Script MT Bold&quot;;">
              <span style="color: black;">
                <span style="">Your partners at Church Mutual Insurance
                  Company, S.I.</span></span></span></span></span></span></span></span></p>', NULL, N'general', CAST(N'2021-12-08T16:01:28.1640000' AS DateTime2), CAST(N'2022-01-02T15:59:00.0000000' AS DateTime2), 0, 0)
GO
INSERT [dbo].[AnnouncementsEntry] ([uuid_], [entryId], [companyId], [userId], [userName], [createDate], [modifiedDate], [classNameId], [classPK], [title], [content], [url], [type_], [displayDate], [expirationDate], [priority], [alert]) VALUES (N'1c0beac8-d536-6048-e142-24c144bb2230', 448865, 20102, 320298, N'Michael Heinrich', CAST(N'2021-12-14T13:38:25.0770000' AS DateTime2), CAST(N'2021-12-14T13:38:25.0770000' AS DateTime2), 20001, 292110, N'Did you know?', N'<p>You can get a Certificate of Insurance or Evidence of Property
  Insurance form in under a minute! Click the Request a Certificate
  button on the dashboard page to get started.</p>', NULL, N'general', CAST(N'2021-12-14T13:38:25.0720000' AS DateTime2), CAST(N'2022-01-14T13:38:00.0000000' AS DateTime2), 0, 0)
GO
INSERT [dbo].[AnnouncementsEntry] ([uuid_], [entryId], [companyId], [userId], [userName], [createDate], [modifiedDate], [classNameId], [classPK], [title], [content], [url], [type_], [displayDate], [expirationDate], [priority], [alert]) VALUES (N'2dd6f951-2e16-bb7c-355c-a537454dc16b', 492631, 20102, 320298, N'Michael Heinrich', CAST(N'2022-01-13T18:03:56.1100000' AS DateTime2), CAST(N'2022-01-13T18:03:56.1100000' AS DateTime2), 20001, 292005, N'Time-Sensitive Information to Share with your Church Mutual WC Clients', N'<p>
  <span style="font-size: 11.0pt;">
    <span style="font-family: Calibri , sans-serif;">
      <span style="color: rgb(0,32,96);">We recently learned Medcor is
        experiencing a significant delay in response time due to illness
        within their staff. Compounding the issue is a surge of incoming
        Covid calls and average call wait times are approximately 25
        minutes. While Medcor provides an excellent service, we
        understand that you may feel this wait time to be excessive.
        Therefore, we are recommending policyholders temporarily report
        all new WC claims directly to us, and bypass Medcor (likely for
        the next 2-4 weeks). This includes potential Covid-19
        claims. This recommendation only involves Church Mutual
        customers with WC coverage so please let them know about this
        issue.  </span></span></span></p>
<p>
  <span style="font-size: 11.0pt;">
    <span style="font-family: Calibri , sans-serif;">
      <span style="color: rgb(0,32,96);">The most efficient approach is
        to email a state First Report to </span>
      <a href="mailto:claimsintake@churchmutual.com"
          style="color: rgb(5,99,193);text-decoration: underline;"><span style="color: rgb(0,32,96);">claimsintake@churchmutual.com</span></a>
      <span style="color: rgb(0,32,96);">.</span></span></span></p>
<p>
  <span style="font-size: 11.0pt;">
    <span style="font-family: Calibri , sans-serif;">
      <span style="color: rgb(0,32,96);">First, use the following link. </span></span></span></p>
<p>
  <span style="font-size: 11.0pt;">
    <span style="font-family: Calibri , sans-serif;">
      <a href="https://www.churchmutual.com/72/Claims-Center"
          style="color: rgb(5,99,193);text-decoration: underline;"><span style="color: rgb(5,99,193);">https://www.churchmutual.com/72/Claims-Center</span></a></span></span></p>
<p>
  <span style="font-size: 11.0pt;">
    <span style="font-family: Calibri , sans-serif;">
      <span style="color: rgb(0,32,96);">Within this <b>File a Claim</b>
        link, click on <b>“Email”</b> and then click on <b>“download
          from our website”</b> to select the proper state’s First
        Report. Attach the completed form to your email and mail it to </span>
      <a href="mailto:claimsintake@churchmutual.com" style="color: rgb(5,99,193);text-decoration: underline;">claimsintake@churchmutual.com</a>
      <span style="color: rgb(0,32,96);">. Please be sure to indicate if
        the employee has sought or intends to seek outside medical care
        so we can properly categorize the loss as either a Notice Only
        or Standard claim.</span></span></span></p>
<p>
  <span style="font-size: 11.0pt;">
    <span style="font-family: Calibri , sans-serif;">
      <span style="color: rgb(0,32,96);">Our Medcor toll-free number
        will remain active, and Medcor will still take calls and provide
        excellent decision support to anyone who wants to call despite
        the wait-time issue.    </span></span></span></p>
<p>
  <span style="font-size: 11.0pt;">
    <span style="font-family: Calibri , sans-serif;">
      <span style="color: rgb(0,32,96);">For California Covid-19 cases,
        the claim reporting process remains unchanged.  </span></span></span></p>
<p>
  <span style="font-size: 11.0pt;">
    <span style="font-family: Calibri , sans-serif;">
      <span style="color: rgb(0,32,96);">Thanks for the understanding,
        and we will do all we can to help Medcor reinstate the service
        you’re used to receiving. Of course, we will keep everyone
        apprised as the situation improves.      </span></span></span></p>
<p>
  <span style="font-size: 11.0pt;">
    <span style="font-family: Calibri , sans-serif;">
      <u>
        <span style="color: rgb(0,32,96);">Please help us by sharing
          this information within your organization, and across your
          Church Mutual workers’ compensation clients</span></u>
      <span style="color: rgb(0,32,96);">.</span></span></span></p>', NULL, N'general', CAST(N'2022-01-13T18:03:56.1020000' AS DateTime2), CAST(N'2022-01-22T18:02:00.0000000' AS DateTime2), 0, 0)
GO
