INSERT [dbo].[AnnouncementsEntry] ([uuid_], [entryId], [companyId], [userId], [userName], [createDate], [modifiedDate], [classNameId], [classPK], [title], [content], [url], [type_], [displayDate], [expirationDate], [priority], [alert]) VALUES (N'999d0614-79ce-df35-a362-62409351580a', 1128888, 20102, 723170, N'Ashley Krebaum', CAST(N'2022-12-20T20:31:37.5870000' AS DateTime2), CAST(N'2022-12-20T21:31:38.0480000' AS DateTime2), 20001, 292110, N'Prepare for Freezing Temperatures', N'<p style="margin-bottom: 11.0px;">
  <span style="font-size: 11.0pt;">
    <span style="background: white;">
      <span style="line-height: normal;">
        <span style="font-family: Calibri , sans-serif;">
          <span style="font-size: 10.5pt;">
            <span style="font-family: &quot;Segoe UI&quot; , sans-serif;">
              <span style="color: rgb(36,36,36);">Dear Valued Customer,</span></span></span></span></span></span></span></p>
<p style="margin-bottom: 11.0px;">
  <span style="font-size: 11.0pt;">
    <span style="background: white;">
      <span style="line-height: normal;">
        <span style="font-family: Calibri , sans-serif;">
          <span style="font-size: 10.5pt;">
            <span style="font-family: &quot;Segoe UI&quot; , sans-serif;">
              <span style="color: rgb(36,36,36);">Severe winter weather
                is expected across the country this week. Is your
                facility prepared for sub-freezing temperatures,
                including the possibility of frozen pipes?</span></span></span></span></span></span></span></p>
<p style="margin-bottom: 11.0px;">
  <span style="font-size: 11.0pt;">
    <span style="background: white;">
      <span style="line-height: normal;">
        <span style="font-family: Calibri , sans-serif;">
          <span style="font-size: 10.5pt;">
            <span style="font-family: &quot;Segoe UI&quot; , sans-serif;">
              <span style="color: rgb(36,36,36);">To help you weather
                these conditions, we want to share with you our </span></span></span>
          <span style="color: black;">
            <a
              href="https://cmgroup.widen.net/view/pdf/gdsla2s2y6/Winter-Storm-Freeze-Preparedness-Plan-RC-CM0653-2022-08.pdf?t.download=true&amp;use=f0vz6ylb&amp;x.portal_shortcode_generated=iz7q955e&amp;x.collection_sharename=u7adbal5&amp;x.app=portals"
              style="color: rgb(5,99,193);text-decoration: underline;"
                target="_blank"><span style="font-size: 10.5pt;">
                <span
                  style="font-family: &quot;Segoe UI&quot; , sans-serif;">Winter
                  Storm and Freeze Preparedness Plan</span></span></a></span>
          <span style="font-size: 10.5pt;">
            <span style="font-family: &quot;Segoe UI&quot; , sans-serif;">
              <span style="color: rgb(36,36,36);">. The plan provides
                important information on how to protect your facility
                and prevent your pipes from freezing in the event of
                power or heat loss. </span></span></span></span></span></span></span></p>
<p style="margin-bottom: 11.0px;">
  <span style="font-size: 11.0pt;">
    <span style="background: white;">
      <span style="line-height: normal;">
        <span style="font-family: Calibri , sans-serif;">
          <span style="font-size: 10.5pt;">
            <span style="font-family: &quot;Segoe UI&quot; , sans-serif;">
              <span style="color: rgb(36,36,36);">If you have any
                questions, please contact Church Mutual </span></span></span>
          <span style="font-size: 12.0pt;">
            <span style="color: rgb(36,36,36);">Customer Service at </span></span>
          <span style="font-size: 12.0pt;">
            <span style="background: white;">
              <span style="color: rgb(51,51,51);">800-554-2642, Option 4.</span></span></span></span></span></span></span></p>', NULL, N'general', CAST(N'2022-12-20T20:31:00.0000000' AS DateTime2), CAST(N'2022-12-21T20:28:00.0000000' AS DateTime2), 1, 0)
GO
