INSERT [dbo].[DDMTemplate] ([mvccVersion], [uuid_], [templateId], [groupId], [companyId], [userId], [userName], [versionUserId], [versionUserName], [createDate], [modifiedDate], [classNameId], [classPK], [resourceClassNameId], [templateKey], [version], [name], [description], [type_], [mode_], [language], [script], [cacheable], [smallImage], [smallImageId], [smallImageURL], [lastPublishDate]) VALUES (0, N'f6d35732-3bde-756f-5fa2-2f6033e8cd69', 285229, 20129, 20102, 20106, NULL, 20106, NULL, CAST(N'2021-03-25T19:53:36.5980000' AS DateTime2), CAST(N'2021-03-25T19:53:36.5980000' AS DateTime2), 285214, 0, 285216, N'RSS-NAVIGATION-FTL', N'1.0', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Name language-id="en_US">Navigation</Name></root>', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Description language-id="en_US">Displays the RSS feeds as a navigation bar on the left panel. Clicking on a feed displays a list of feed entries on the right panel.</Description></root>', N'display', NULL, N'ftl', N'<#assign rssPortletInstanceConfiguration = rssDisplayContext.getRSSPortletInstanceConfiguration() />

<style>
	.portlet-rss .feed-entry-content {
		margin-bottom: 20px;
		padding-left: 0;
	}
</style>

<#if entries?has_content>
	<#assign dateFormat = "dd MMM yyyy - HH:mm:ss" />

	<div class="container-fluid">
		<div class="row" id="<@portlet.namespace />feedsTab">
			<ul class="col-xs-4">
				<#list entries as curEntry>
					<li><a href="#tab-${curEntry_index}">${htmlUtil.escape(curEntry.getTitle())}</a></li>
				</#list>
			</ul>

			<div class="col-xs-8 tab-content">
				<#list entries as curEntry>
					<#assign rssFeedEntries = curEntry.getRSSFeedEntries(themeDisplay) />

					<#if rssFeedEntries??>
						<div class="tab-pane" id="tab-${curEntry_index}">
							<#list rssFeedEntries as rssFeedEntry>
								<#if (rssFeedEntry_index > entriesPerFeed?number)>
									<#break>
								</#if>

								<#assign syndEntry = rssFeedEntry.getSyndEntry() />

								<div class="feed-entry-content">
									<div class="feed-title">
										<@liferay_aui["a"] href="${htmlUtil.escapeJSLink(rssFeedEntry.getSyndEntryLink())}">${htmlUtil.escape(syndEntry.getTitle())}</@>
									</div>

									<#if rssPortletInstanceConfiguration.showFeedTitle() && syndEntry.getAuthor()??>
										<div class="feed-entry-author">
											${htmlUtil.escape(syndEntry.getAuthor())}
										</div>
									</#if>

									<#if syndEntry.getPublishedDate()??>
										<div class="feed-date">
											<@liferay_ui["icon"]
												icon="calendar"
												label=true
												markupView="lexicon"
												message="${dateUtil.getDate(syndEntry.getPublishedDate(), dateFormat, locale)}"
											/>
										</div>
									</#if>

									${rssFeedEntry.getSanitizedContent()}
								</div>
							</#list>
						</div>
					</#if>
				</#list>
			</div>
		</div>
	</div>

	<@liferay_aui["script"] use="aui-base,aui-tabview">
		new A.TabView(
			{
				srcNode: ''#<@portlet.namespace />feedsTab'',
				stacked: true,
				type: ''pills''
			}
		).render();
	</@>
</#if>', 0, 0, 285230, NULL, NULL)
GO
INSERT [dbo].[DDMTemplate] ([mvccVersion], [uuid_], [templateId], [groupId], [companyId], [userId], [userName], [versionUserId], [versionUserName], [createDate], [modifiedDate], [classNameId], [classPK], [resourceClassNameId], [templateKey], [version], [name], [description], [type_], [mode_], [language], [script], [cacheable], [smallImage], [smallImageId], [smallImageURL], [lastPublishDate]) VALUES (0, N'478ff7c3-1d69-39ee-f1cc-00283ec1f131', 285232, 20129, 20102, 20106, NULL, 20106, NULL, CAST(N'2021-03-25T19:53:36.6380000' AS DateTime2), CAST(N'2021-03-25T19:53:36.6380000' AS DateTime2), 20172, 0, 285216, N'LIST-MENU-FTL', N'1.0', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Name language-id="en_US">List Menu</Name></root>', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Description language-id="en_US">Displays a navigation menu with a list.</Description></root>', N'display', NULL, N'ftl', N'<#include "${templatesPath}/NAVIGATION-MACRO-FTL" />

<#if !entries?has_content>
	<#if themeDisplay.isSignedIn()>
		<div class="alert alert-info">
			<@liferay.language key="there-are-no-menu-items-to-display" />
		</div>
	</#if>
<#else>
	<#assign includeAllChildNavItems = false />

	<#if stringUtil.equals(includedLayouts, "all")>
		<#assign includeAllChildNavItems = true />
	</#if>

	<div aria-label="<@liferay.language key="site-pages" />" class="list-menu">
		<@buildNavigation
			branchNavItems=branchNavItems
			cssClass="layouts"
			displayDepth=displayDepth
			includeAllChildNavItems=includeAllChildNavItems
			navItemLevel=1
			navItems=entries
		/>
	</div>
</#if>', 0, 0, 285233, NULL, NULL)
