INSERT [dbo].[DDMTemplate] ([mvccVersion], [uuid_], [templateId], [groupId], [companyId], [userId], [userName], [versionUserId], [versionUserName], [createDate], [modifiedDate], [classNameId], [classPK], [resourceClassNameId], [templateKey], [version], [name], [description], [type_], [mode_], [language], [script], [cacheable], [smallImage], [smallImageId], [smallImageURL], [lastPublishDate]) VALUES (8, N'7029bca6-5bd1-1fd3-1dcc-3fbc0107ae06', 285259, 20129, 20102, 20106, NULL, 20106, NULL, CAST(N'2021-03-25T19:53:37.2950000' AS DateTime2), CAST(N'2023-12-06T14:45:19.2280000' AS DateTime2), 20172, 0, 285216, N'NAVIGATION-MACRO-FTL', N'1.8', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Name language-id="en_US">Navigation common macros</Name></root>', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Description language-id="en_US">Contains common macros for navigation menu templates.</Description></root>', N'macro', NULL, N'ftl', N'<#macro buildNavigation
	branchNavItems
	cssClass
	displayDepth
	includeAllChildNavItems
	navItemLevel
	navItems
>
	<#if navItems?has_content && ((displayDepth == 0) || (navItemLevel <= displayDepth))>
		<ul class="${cssClass} level-${navItemLevel}">
			<#list navItems as navItem>
				<#assign
					nav_item_css_class = "lfr-nav-item"
				/>

				<#if includeAllChildNavItems || navItem.isInNavigation(branchNavItems)>
					<#assign nav_item_css_class = "${nav_item_css_class} open" />
				</#if>

				<#if navItem.isChildSelected() || navItem.isSelected()>
					<#assign
						nav_item_css_class = "${nav_item_css_class} selected active"
					/>
				</#if>

				<li class="${nav_item_css_class}">
					<#if navItem.isBrowsable()>
						<a class="${nav_item_css_class}" href="${navItem.getRegularURL()!""}" ${navItem.getTarget()}>${navItem.getName()}</a>
					<#else>
						${navItem.getName()}
					</#if>

					<#if includeAllChildNavItems || navItem.isInNavigation(branchNavItems)>
						<@buildNavigation
							branchNavItems=branchNavItems
							cssClass=cssClass
							displayDepth=displayDepth
							includeAllChildNavItems=includeAllChildNavItems
							navItemLevel=(navItemLevel + 1)
							navItems=navItem.getChildren()
						/>
					</#if>
				</li>
			</#list>
		</ul>
	</#if>
</#macro>', 0, 0, 285260, NULL, NULL)
GO
INSERT [dbo].[DDMTemplate] ([mvccVersion], [uuid_], [templateId], [groupId], [companyId], [userId], [userName], [versionUserId], [versionUserName], [createDate], [modifiedDate], [classNameId], [classPK], [resourceClassNameId], [templateKey], [version], [name], [description], [type_], [mode_], [language], [script], [cacheable], [smallImage], [smallImageId], [smallImageURL], [lastPublishDate]) VALUES (8, N'cc444f73-6994-7a78-e42a-3c674552c6ab', 285262, 20129, 20102, 20106, NULL, 20106, NULL, CAST(N'2021-03-25T19:53:37.3300000' AS DateTime2), CAST(N'2023-12-06T14:45:19.2750000' AS DateTime2), 20172, 0, 285216, N'SPLIT-BUTTON-DROPDOWNS-FTL', N'1.8', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Name language-id="en_US">Split Button Dropdowns</Name></root>', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Description language-id="en_US">Displays a dropdown navigation menu with root menu items shown as buttons.</Description></root>', N'display', NULL, N'ftl', N'<#if !entries?has_content>
	<#if themeDisplay.isSignedIn()>
		<div class="alert alert-info">
			<@liferay.language key="there-are-no-menu-items-to-display" />
		</div>
	</#if>
<#else>
	<#assign
		portletDisplay = themeDisplay.getPortletDisplay()

		navbarId = "navbar_" + portletDisplay.getId()
	/>

	<div id="${navbarId}">
		<ul class="navbar-site split-button-dropdowns">
			<#assign navItems = entries />

			<#list navItems as navItem>
				<#assign showChildren = (displayDepth != 1) && navItem.hasBrowsableChildren() />

				<#if navItem.isBrowsable() || showChildren>
					<#assign
						nav_item_caret = ""
						nav_item_css_class = ""
						nav_item_href_link = ""
					/>

					<#if navItem.isChildSelected() || navItem.isSelected()>
						<#assign nav_item_css_class = "active" />
					</#if>

					<#if showChildren>
						<#assign toggle_text>
							<@liferay.language key="toggle" />
						</#assign>

						<#assign nav_item_caret = "<button aria-expanded=''false'' aria-haspopup=''true'' class=''${nav_item_css_class} btn btn-default dropdown-toggle'' data-toggle=''dropdown'' type=''button''><span class=''caret''></span><span class=''sr-only''>${toggle_text}</span></button>" />
					</#if>

					<#if navItem.isBrowsable()>
						<#assign nav_item_href_link = "href=''${navItem.getURL()}'' ${navItem.getTarget()}" />
					</#if>

					<li>
						<a class="${nav_item_css_class} btn btn-default" ${nav_item_href_link}><span>${navItem.getName()}</span></a>${nav_item_caret}

						<#if showChildren>
							<ul class="child-menu dropdown-menu" role="menu">
								<#list navItem.getBrowsableChildren() as childNavigationItem>
									<#assign
										nav_child_css_class = ""
									/>

									<#if childNavigationItem.isSelected()>
										<#assign
											nav_child_css_class = "active"
										/>
									</#if>

									<li class="${nav_child_css_class}" id="layout_${portletDisplay.getId()}_${childNavigationItem.getLayoutId()}" role="presentation">
										<a href="${childNavigationItem.getURL()}" ${childNavigationItem.getTarget()} role="menuitem">${childNavigationItem.getName()}</a>
									</li>
								</#list>
							</ul>
						</#if>
					</li>
				</#if>
			</#list>
		</ul>
	</div>

	<@liferay_aui.script use="liferay-navigation-interaction">
		var navigation = A.one(''#${navbarId}'');

		Liferay.Data.NAV_INTERACTION_LIST_SELECTOR = ''.navbar-site'';
		Liferay.Data.NAV_LIST_SELECTOR = ''.navbar-site'';

		if (navigation) {
			navigation.plug(Liferay.NavigationInteraction);
		}
	</@>
</#if>', 0, 0, 285263, NULL, NULL)
GO
INSERT [dbo].[DDMTemplate] ([mvccVersion], [uuid_], [templateId], [groupId], [companyId], [userId], [userName], [versionUserId], [versionUserName], [createDate], [modifiedDate], [classNameId], [classPK], [resourceClassNameId], [templateKey], [version], [name], [description], [type_], [mode_], [language], [script], [cacheable], [smallImage], [smallImageId], [smallImageURL], [lastPublishDate]) VALUES (7, N'60acb427-3376-3728-9292-98d638ee84b4', 285265, 20129, 20102, 20106, NULL, 20106, NULL, CAST(N'2021-03-25T19:53:37.4050000' AS DateTime2), CAST(N'2023-12-06T14:45:19.3200000' AS DateTime2), 285215, 0, 285216, N'LANGUAGE-ICON-FTL', N'1.7', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Name language-id="en_US">Icon</Name></root>', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Description language-id="en_US">Displays the icon of the flag associated with each language.</Description></root>', N'display', NULL, N'ftl', N'<#if entries?has_content>
