INSERT [dbo].[DDMTemplate] ([mvccVersion], [uuid_], [templateId], [groupId], [companyId], [userId], [userName], [versionUserId], [versionUserName], [createDate], [modifiedDate], [classNameId], [classPK], [resourceClassNameId], [templateKey], [version], [name], [description], [type_], [mode_], [language], [script], [cacheable], [smallImage], [smallImageId], [smallImageURL], [lastPublishDate]) VALUES (0, N'd68d90c7-a54e-ccd2-ff6d-034283906d29', 285268, 20129, 20102, 20106, NULL, 20106, NULL, CAST(N'2021-03-25T19:53:37.4430000' AS DateTime2), CAST(N'2021-03-25T19:53:37.4430000' AS DateTime2), 285215, 0, 285216, N'LANGUAGE-ICON-MENU-FTL', N'1.0', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Name language-id="en_US">Icon Menu</Name></root>', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Description language-id="en_US">Displays an icon menu with the selected languages.</Description></root>', N'display', NULL, N'ftl', N'<#if entries?has_content>
	<#assign normalizedDefaultLanguageId = stringUtil.replace(languageId, "_", "-") />

	<div class="truncate-text">
		<@liferay_ui["icon-menu"]
			direction="left-side"
			icon=stringUtil.toLowerCase(normalizedDefaultLanguageId)
			markupView="lexicon"
			showWhenSingleIcon=true
			triggerLabel=normalizedDefaultLanguageId
			triggerType="button"
		>
			<#list entries as entry>
				<#if !entry.isSelected() && !entry.isDisabled()>
					<#assign
						entryLocale = entry.getLocale()
						displayName = stringUtil.toLowerCase(entryLocale.getDisplayLanguage(entryLocale)) + "-" + entryLocale.getDisplayCountry(entryLocale)
						normalizedDefaultLanguageId = stringUtil.toLowerCase(stringUtil.replace(entry.getLanguageId(), "_", "-"))
					/>

					<#if languageUtil.isBetaLocale(entryLocale)>
						<#assign displayName += " [beta]" />
					</#if>

					<@liferay_ui["icon"]
						icon=normalizedDefaultLanguageId
						iconCssClass="inline-item inline-item-before"
						markupView="lexicon"
						message=displayName
						url=entry.getURL()
					/>
				</#if>
			</#list>
		</@>
	</div>
</#if>', 0, 0, 285269, NULL, NULL)
GO
INSERT [dbo].[DDMTemplate] ([mvccVersion], [uuid_], [templateId], [groupId], [companyId], [userId], [userName], [versionUserId], [versionUserName], [createDate], [modifiedDate], [classNameId], [classPK], [resourceClassNameId], [templateKey], [version], [name], [description], [type_], [mode_], [language], [script], [cacheable], [smallImage], [smallImageId], [smallImageURL], [lastPublishDate]) VALUES (0, N'065a0a41-3ca3-f56e-6089-3a78249e3374', 285271, 20129, 20102, 20106, NULL, 20106, NULL, CAST(N'2021-03-25T19:53:37.4780000' AS DateTime2), CAST(N'2021-03-25T19:53:37.4780000' AS DateTime2), 285215, 0, 285216, N'LANGUAGE-LONG-TEXT-FTL', N'1.0', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Name language-id="en_US">Long Text</Name></root>', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Description language-id="en_US">Displays the full name of each language (e.g. Spanish).</Description></root>', N'display', NULL, N'ftl', N'<style>
