INSERT [dbo].[DDMTemplate] ([mvccVersion], [uuid_], [templateId], [groupId], [companyId], [userId], [userName], [versionUserId], [versionUserName], [createDate], [modifiedDate], [classNameId], [classPK], [resourceClassNameId], [templateKey], [version], [name], [description], [type_], [mode_], [language], [script], [cacheable], [smallImage], [smallImageId], [smallImageURL], [lastPublishDate]) VALUES (0, N'a3c35d39-b5f9-d928-a588-000ac5157ac9', 285274, 20129, 20102, 20106, NULL, 20106, NULL, CAST(N'2021-03-25T19:53:37.5130000' AS DateTime2), CAST(N'2021-03-25T19:53:37.5130000' AS DateTime2), 285215, 0, 285216, N'LANGUAGE-SELECT-BOX-FTL', N'1.0', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Name language-id="en_US">Select Box</Name></root>', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Description language-id="en_US">Displays a select box with the selected languages.</Description></root>', N'display', NULL, N'ftl', N'<#if entries?has_content>
	<#assign languageId = localeUtil.toLanguageId(locale) />

	<style>
		.taglib-language-option {
			background: none no-repeat 5px center;
			padding-left: 25px;
		}

		<#list entries as entry>
			.taglib-language-option-${entry.getW3cLanguageId()} {
				background-image: url(${themeDisplay.getPathThemeImages()}/language/${entry.getLanguageId()}.png);
			}
		</#list>
	</style>

	<@liferay_aui["form"]
		action=formAction
		method="post"
		name=''${namespace + formName}''
		useNamespace=false
	>
		<@liferay_aui["select"]
			changesContext=true
			id=''${namespace + formName}''
			label=""
			name=''${name}''
			onChange=''${namespace + "changeLanguage();"}''
			title="language"
		>
			<#list entries as entry>
				<@liferay_aui["option"]
					cssClass="taglib-language-option taglib-language-option-${entry.getW3cLanguageId()}"
					disabled=entry.isDisabled()
					label=entry.getLongDisplayName()
					lang=entry.getW3cLanguageId()
					localizeLabel=false
					selected=entry.isSelected()
					value=entry.getLanguageId()
				/>
			</#list>
		</@>
	</@>

	<@liferay_aui["script"]>
		function ${namespace}changeLanguage() {
			submitForm(document.${namespace + formName});
		}
	</@>
</#if>', 0, 0, 285275, NULL, NULL)
