INSERT [dbo].[DDMTemplate] ([mvccVersion], [uuid_], [templateId], [groupId], [companyId], [userId], [userName], [versionUserId], [versionUserName], [createDate], [modifiedDate], [classNameId], [classPK], [resourceClassNameId], [templateKey], [version], [name], [description], [type_], [mode_], [language], [script], [cacheable], [smallImage], [smallImageId], [smallImageURL], [lastPublishDate]) VALUES (0, N'd5377f41-431e-3ab7-3834-d9850c3c753b', 285277, 20129, 20102, 20106, NULL, 20106, NULL, CAST(N'2021-03-25T19:53:37.5530000' AS DateTime2), CAST(N'2021-03-25T19:53:37.5530000' AS DateTime2), 285215, 0, 285216, N'LANGUAGE-SHORT-TEXT-FTL', N'1.0', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Name language-id="en_US">Short Text</Name></root>', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Description language-id="en_US">Displays an abbreviation of each language (e.g. ES).</Description></root>', N'display', NULL, N'ftl', N'<style>
