INSERT [dbo].[DDMTemplateVersion] ([mvccVersion], [templateVersionId], [groupId], [companyId], [userId], [userName], [createDate], [classNameId], [classPK], [templateId], [version], [name], [description], [language], [script], [status], [statusByUserId], [statusByUserName], [statusDate]) VALUES (0, 285219, 20129, 20102, 20106, NULL, CAST(N'2021-03-25T19:53:36.3880000' AS DateTime2), 285212, 0, 285217, N'1.0', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Name language-id="en_US">Arrows</Name></root>', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Description language-id="en_US">Displays a breadcrumb in which every navigation element is represented by an arrow with its title and link.</Description></root>', N'ftl', N'<#if entries?has_content>
	<@liferay_util["html-top"]>
		<style>
			.breadcrumb-arrows li {
				background-color: #EFEFEF;
				margin-bottom: 3px;
				overflow: visible;
			}

			.breadcrumb-arrows li + li::before {
				content: none;
			}

			.breadcrumb-arrows li > a {
				border-right: 4px solid #FFF;
				display: block;
				max-width: 100%;
				position: relative;
			}

			.breadcrumb-arrows .entry {
				line-height: 40px;
				overflow: hidden;
				padding-left: 30px;
				padding-right: 7px;
				text-overflow: ellipsis;
				white-space: nowrap;
			}

			.breadcrumb-arrows a::after {
				border-bottom: 20px inset transparent;
				border-left: 20px solid #EFEFEF;
				border-top: 20px inset transparent;
				content: '''';
				height: 0;
				position: absolute;
				right: -20px;
				top: 0;
				width: 0;
				z-index: 2;
			}

			.breadcrumb-arrows li:nth-child(n+2) a::before {
				border-bottom: 20px inset transparent;
				border-left: 20px solid #FFF;
				border-top: 20px inset transparent;
				content: '''';
				height: 0;
				left: 0;
				position: absolute;
				top: 0;
				width: 0;
			}

			.breadcrumb-arrows li:last-child {
				border-bottom-right-radius: 4px;
				border-right-width: 0;
				border-top-right-radius: 4px;
				position: relative;
			}

			.breadcrumb-arrows li:last-child::before {
				border-bottom: 20px inset transparent;
				border-left: 20px solid #FFF;
				border-top: 20px inset transparent;
				content: '''';
				height: 0;
				left: 0;
				position: absolute;
				top: 0;
				width: 0;
			}

			.breadcrumb-arrows li:last-child .entry {
				padding-right: 23px;
			}

			.breadcrumb-arrows li:first-child {
				border-bottom-left-radius: 4px;
				border-top-left-radius: 4px;
			}

			.breadcrumb-arrows li:first-child::before {
				border-left-width: 0;
			}

			.breadcrumb-arrows li:first-child .entry {
				padding-left: 23px;
			}

			.breadcrumb-arrows .active {
				background-color: #007ACC;
			}

			.breadcrumb-arrows .active a, .breadcrumb-arrows .active .entry {
				color: #FFF;
			}

			.breadcrumb-arrows .active a::after {
				border-left-color: #007ACC;
			}

			.portlet-barebone .breadcrumb-arrows li > a, .portlet-borderless .breadcrumb-arrows li > a, .taglib-portlet-preview .breadcrumb-arrows li > a {
				border-right-color: #F5F7F8;
			}

			.portlet-barebone .breadcrumb-arrows li:last-child::before, .portlet-barebone .breadcrumb-arrows li:nth-child(n+2) a::before, .portlet-borderless .breadcrumb-arrows li:last-child::before, .portlet-borderless .breadcrumb-arrows li:nth-child(n+2) a::before, .taglib-portlet-preview .breadcrumb-arrows li:last-child::before, .taglib-portlet-preview .breadcrumb-arrows li:nth-child(n+2) a::before {
				border-left-color: #F5F7F8;
			}
		</style>
	</@>

	<div class="breadcrumb breadcrumb-arrows">
		<#assign cssClass = "" />

		<#list entries as entry>
			<#if entry?is_last>
				<#assign cssClass = "active" />
			</#if>

			<li class="${cssClass}" <#if entry?is_last>aria-current="page"</#if>>
				<#if entry?has_next>
					<a

					<#if entry.isBrowsable()>
						href="${entry.getURL()!""}"
					</#if>

					>
				</#if>

				<div class="entry">
					${htmlUtil.escape(entry.getTitle())}
				</div>

				<#if entry?has_next>
					</a>
				</#if>
			</li>
		</#list>
	</div>
</#if>', 0, 20106, NULL, CAST(N'2021-03-25T19:53:36.3880000' AS DateTime2))
GO
INSERT [dbo].[DDMTemplateVersion] ([mvccVersion], [templateVersionId], [groupId], [companyId], [userId], [userName], [createDate], [classNameId], [classPK], [templateId], [version], [name], [description], [language], [script], [status], [statusByUserId], [statusByUserName], [statusDate]) VALUES (0, 285222, 20129, 20102, 20106, NULL, CAST(N'2021-03-25T19:53:36.4780000' AS DateTime2), 285212, 0, 285220, N'1.0', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Name language-id="en_US">Horizontal</Name></root>', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Description language-id="en_US">Displays a breadcrumb horizontally.</Description></root>', N'ftl', N'<#if entries?has_content>
	<ol class="breadcrumb">
		<#list entries as entry>
			<li class="breadcrumb-item">
				<#if entry?has_next>
					<a class="breadcrumb-link" href="${entry.getURL()!""}" title="${htmlUtil.escape(entry.getTitle())}">
						<span class="breadcrumb-text-truncate">${htmlUtil.escape(entry.getTitle())}</span>
					</a>
				<#else>
					<span class="active breadcrumb-text-truncate">${htmlUtil.escape(entry.getTitle())}</span>
				</#if>
			</li>
		</#list>
	</ol>
</#if>', 0, 20106, NULL, CAST(N'2021-03-25T19:53:36.4780000' AS DateTime2))
GO
INSERT [dbo].[DDMTemplateVersion] ([mvccVersion], [templateVersionId], [groupId], [companyId], [userId], [userName], [createDate], [classNameId], [classPK], [templateId], [version], [name], [description], [language], [script], [status], [statusByUserId], [statusByUserName], [statusDate]) VALUES (0, 285225, 20129, 20102, 20106, NULL, CAST(N'2021-03-25T19:53:36.5130000' AS DateTime2), 285212, 0, 285223, N'1.0', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Name language-id="en_US">Vertical</Name></root>', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Description language-id="en_US">Displays a breadcrumb vertically.</Description></root>', N'ftl', N'<#if entries?has_content>
	<ul class="breadcrumb breadcrumb-vertical">
		<#assign cssClass = "" />

