INSERT [dbo].[DDMTemplateVersion] ([mvccVersion], [templateVersionId], [groupId], [companyId], [userId], [userName], [createDate], [classNameId], [classPK], [templateId], [version], [name], [description], [language], [script], [status], [statusByUserId], [statusByUserName], [statusDate]) VALUES (0, 290040, 20129, 20102, 20106, NULL, CAST(N'2021-03-25T19:53:40.8750000' AS DateTime2), 285180, 290034, 290038, N'1.0', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Name language-id="en_US">Basic Web Content</Name></root>', N'', N'ftl', N'${content.getData()}', 0, 20106, NULL, CAST(N'2021-03-25T19:53:40.8750000' AS DateTime2))
