INSERT [dbo].[DDMTemplateVersion] ([mvccVersion], [templateVersionId], [groupId], [companyId], [userId], [userName], [createDate], [classNameId], [classPK], [templateId], [version], [name], [description], [language], [script], [status], [statusByUserId], [statusByUserName], [statusDate]) VALUES (0, 292163, 292110, 20102, 20106, NULL, CAST(N'2021-03-25T19:53:57.2320000' AS DateTime2), 285180, 290034, 292161, N'1.0', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Name language-id="en_US">File A Claim</Name></root>', N'', N'ftl', N'<div class="file-a-claim-link">

	<div class="my-3 py-3">
