INSERT [dbo].[DDMTemplateVersion] ([mvccVersion], [templateVersionId], [groupId], [companyId], [userId], [userName], [createDate], [classNameId], [classPK], [templateId], [version], [name], [description], [language], [script], [status], [statusByUserId], [statusByUserName], [statusDate]) VALUES (0, 312514, 20129, 20102, 20106, NULL, CAST(N'2021-03-25T19:53:37.7880000' AS DateTime2), 238001, 0, 285295, N'1.1', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Name language-id="en_US">Card</Name></root>', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Description language-id="en_US">Display cover images, titles, authors and abstracts using cards for blog entries.</Description></root>', N'ftl', N'<div class="row widget-mode-card">
