INSERT [dbo].[DDMTemplateVersion] ([mvccVersion], [templateVersionId], [groupId], [companyId], [userId], [userName], [createDate], [classNameId], [classPK], [templateId], [version], [name], [description], [language], [script], [status], [statusByUserId], [statusByUserName], [statusDate]) VALUES (0, 1784141, 292005, 20102, 1031126, N'Noah Plautz', CAST(N'2023-09-11T19:23:48.2800000' AS DateTime2), 285180, 290034, 1784139, N'1.0', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Name language-id="en_US">Producer - Contact Us</Name></root>', N'', N'ftl', N'<#if layout.getFriendlyURL(locale) == "/dashboard">
	<#assign lg = "12" />
<#else>
	<#assign lg = "4" />
</#if>

<div class="card">
	<div class="card-header">
		<p class="card-title" title="Contact Us">
			<span class="text-truncate-inline">
				<span class="text-truncate">Contact Us</span>
			</span>
		</p>
	</div>

	<div class="card-body">
		<@liferay_aui.row>
<@liferay_aui.col
	lg="${lg}"
	md="6"
>
				<div class="align-items-center user-card">
					<div class="user-card-image">
						<span class="elevation-6 sticker sticker-blue sticker-circle sticker-xxl">
							<span class="sticker-overlay">
								<svg class="lexicon-icon lexicon-icon-envelope-closed">
									<use xlink:href="${themeDisplay.getPathThemeImages()}/clay/icons.svg#envelope-closed" />
								</svg>
							</span>
						</span>
					</div>

					<div class="user-card-body">
						<h4 class="user-card-title">Claim Service Coordinator</h4>

						<div class="user-card-text">
							<a href="mailto:brokerclaimservices@churchmutual.com">brokerclaimservices@churchmutual.com</a>
						</div>
					</div>
				</div>
			</@>
<@liferay_aui.col
	lg="${lg}"
	md="6"
>
				<div class="align-items-center user-card">
					<div class="user-card-image">
						<span class="elevation-6 sticker sticker-circle sticker-green sticker-xxl">
							<span class="sticker-overlay">
								<svg class="lexicon-icon lexicon-icon-envelope-closed">
									<use xlink:href="${themeDisplay.getPathThemeImages()}/clay/icons.svg#envelope-closed" />
								</svg>
							</span>
						</span>
					</div>

					<div class="user-card-body">
