INSERT [dbo].[DDMTemplateVersion] ([mvccVersion], [templateVersionId], [groupId], [companyId], [userId], [userName], [createDate], [classNameId], [classPK], [templateId], [version], [name], [description], [language], [script], [status], [statusByUserId], [statusByUserName], [statusDate]) VALUES (0, 1814924, 20129, 20102, 20106, NULL, CAST(N'2023-11-08T21:12:13.4810000' AS DateTime2), 20017, 0, 285286, N'1.5', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Name language-id="en_US">Color by Popularity</Name></root>', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Description language-id="en_US">Displays asset tags colored by popularity: red (high), yellow (medium), and green (low).</Description></root>', N'ftl', N'<#if entries?has_content>
	<ul class="tag-items tag-list">
		<#assign
			scopeGroupId = getterUtil.getLong(scopeGroupId, themeDisplay.getScopeGroupId())
			classNameId = getterUtil.getLong(classNameId, 0)
			scopedAssetCounts = assetTagsNavigationDisplayContext.getScopedAssetCounts()

			maxCount = 1
			minCount = 1
		/>

		<#list entries as entry>
			<#if scopedAssetCounts??>
				<#assign assetCount = scopedAssetCounts[entry.getName()] />
			<#else>
				<#assign assetCount = entry.getAssetCount() />
			</#if>

			<#if (assetCount > 0) || getterUtil.getBoolean(showZeroAssetCount)>
				<#assign
					maxCount = liferay.max(maxCount, assetCount)
					minCount = liferay.min(minCount, assetCount)
				/>
			</#if>
		</#list>

		<#assign multiplier = 1 />

		<#if maxCount != minCount>
			<#assign multiplier = 3 / (maxCount - minCount) />
		</#if>

		<#list entries as entry>
			<#if scopedAssetCounts??>
				<#assign assetCount = scopedAssetCounts[entry.getName()] />
			<#else>
				<#assign assetCount = entry.getAssetCount() />
			</#if>

			<#if (assetCount > 0) || getterUtil.getBoolean(showZeroAssetCount)>
				<li class="taglib-asset-tags-summary">
					<#assign popularity = (maxCount - (maxCount - (assetCount - minCount))) * multiplier />

					<#if popularity < 1>
						<#assign color = "green" />
					<#elseif (popularity >= 1) && (popularity < 2)>
						<#assign color = "orange" />
					<#else>
						<#assign color = "red" />
					</#if>

					<#assign tagURL = renderResponse.createRenderURL() />

					${tagURL.setParameter("resetCur", "true")}
					${tagURL.setParameter("tag", entry.getName())}

					<a class="tag" href="${tagURL}" style="color: ${color};">
						${entry.getName()}

						<#if assetCount?? && getterUtil.getBoolean(showAssetCount)>
							<span class="tag-asset-count">(${assetCount})</span>
						</#if>
					</a>
				</li>
			</#if>
		</#list>
	</ul>

	<br style="clear: both;" />
</#if>', 0, 20106, NULL, CAST(N'2023-11-08T21:12:13.4810000' AS DateTime2))
GO
INSERT [dbo].[DDMTemplateVersion] ([mvccVersion], [templateVersionId], [groupId], [companyId], [userId], [userName], [createDate], [classNameId], [classPK], [templateId], [version], [name], [description], [language], [script], [status], [statusByUserId], [statusByUserName], [statusDate]) VALUES (0, 1814925, 20129, 20102, 20106, NULL, CAST(N'2023-11-08T21:12:13.2940000' AS DateTime2), 285215, 0, 285265, N'1.5', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Name language-id="en_US">Icon</Name></root>', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Description language-id="en_US">Displays the icon of the flag associated with each language.</Description></root>', N'ftl', N'<#if entries?has_content>
	<#list entries as entry>
		<#if entry.isSelected()>
			<#assign cssClass = "current-language" />
		</#if>

		<#if !entry.isDisabled()>
			<@liferay_aui["icon"]
				ariaLabel=entry.getLongDisplayName()
				cssClass=cssClass
				image=entry.getW3cLanguageId()?lower_case
				markupView="lexicon"
				message=entry.getLongDisplayName()
				url=entry.getURL()
			/>
		</#if>
	</#list>
</#if>', 0, 20106, NULL, CAST(N'2023-11-08T21:12:13.2940000' AS DateTime2))
GO
INSERT [dbo].[DDMTemplateVersion] ([mvccVersion], [templateVersionId], [groupId], [companyId], [userId], [userName], [createDate], [classNameId], [classPK], [templateId], [version], [name], [description], [language], [script], [status], [statusByUserId], [statusByUserName], [statusDate]) VALUES (0, 1814926, 20129, 20102, 20106, NULL, CAST(N'2023-11-08T21:12:13.5870000' AS DateTime2), 200003, 0, 285289, N'1.5', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Name language-id="en_US">Social</Name></root>', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Description language-id="en_US">Displays social bookmarks and ratings for wiki pages and their child pages.</Description></root>', N'ftl', N'<#assign
	wikiPageClassName = "com.liferay.wiki.model.WikiPage"

	assetRenderer = assetEntry.getAssetRenderer()
/>

<div class="taglib-header">
	<h1 class="header-title">${entry.getTitle()}</h1>
</div>

<div style="float: right;">
	<@getEditIcon />

	<@getPageDetailsIcon />

	<@getPrintIcon />
</div>

<div class="wiki-body">
	<div class="wiki-info">
		<span class="stats">${assetEntry.getViewCount()} <@liferay.language key="views" /></span> |

		<span class="date"><@liferay.language key="last-modified" /> ${dateUtil.getDate(entry.getModifiedDate(), "dd MMM yyyy - HH:mm:ss", locale)}</span>

		<span class="author"><@liferay.language key="by" /> ${htmlUtil.escape(portalUtil.getUserName(entry.getUserId(), entry.getUserName()))}</span>
	</div>

	<div class="wiki-content">
		<@liferay_social_bookmarks["bookmarks"]
			className=wikiPageClassName
			classPK=entry.getResourcePrimKey()
			displayStyle="normal"
			target="_blank"
			title=entry.getTitle()
			url=viewURL
		/>

		${formattedContent}
	</div>

	<div class="page-actions">
		<div class="article-actions">
			<@getAddChildPageIcon />

			<@getAttatchmentsIcon />
		</div>
	</div>

	<br />

	<@getRatings
		cssClass="page-ratings"
		entry=entry
	/>

	<@getRelatedAssets />
</div>

<div class="page-categorization">
	<div class="page-categories">
		<#assign viewCategorizedPagesURL = renderResponse.createRenderURL() />

		${viewCategorizedPagesURL.setParameter("mvcRenderCommandName", "/wiki/view_categorized_pages")}
		${viewCategorizedPagesURL.setParameter("nodeId", entry.getNodeId()?string)}

		<@liferay_ui["asset-categories-summary"]
			className=wikiPageClassName
			classPK=entry.getResourcePrimKey()
			portletURL=viewCategorizedPagesURL
		/>
	</div>

	<div class="page-tags">
		<#assign viewTaggedPagesURL = renderResponse.createRenderURL() />

		${viewTaggedPagesURL.setParameter("mvcRenderCommandName", "/wiki/view_tagged_pages")}
		${viewTaggedPagesURL.setParameter("nodeId", entry.getNodeId()?string)}

		<@liferay_ui["asset-tags-summary"]
			className=wikiPageClassName
			classPK=entry.getResourcePrimKey()
			portletURL=viewTaggedPagesURL
		/>
	</div>
</div>

<#assign childPages = entry.getChildPages() />

<#if (childPages?has_content)>
	<div class="child-pages">
		<h2><@liferay.language key="children-pages" /></h2>

		<table class="taglib-search-iterator">
			<tr class="portlet-section-header results-header">
				<th>
					<@liferay.language key="page" />
				</th>
				<th>
					<@liferay.language key="last-modified" />
				</th>
				<th>
					<@liferay.language key="ratings" />
				</th>
			</tr>

			<#list childPages as childPage>
				<tr class="results-row">
					<#assign viewPageURL = renderResponse.createRenderURL() />

					${viewPageURL.setParameter("mvcRenderCommandName", "/wiki/view")}

					<#assign childNode = childPage.getNode() />

					${viewPageURL.setParameter("nodeName", childNode.getName())}
					${viewPageURL.setParameter("title", childPage.getTitle())}

					<td>
						<a href="${viewPageURL}">${childPage.getTitle()}</a>
					</td>
					<td>
						<a href="${viewPageURL}">${dateUtil.getDate(childPage.getModifiedDate(),"dd MMM yyyy - HH:mm:ss", locale)} <@liferay.language key="by" /> ${htmlUtil.escape(portalUtil.getUserName(childPage.getUserId(), childPage.getUserName()))}</a>
					</td>
					<td>
						<@getRatings
							cssClass="child-ratings"
							entry=childPage
						/>
					</td>
				</tr>
			</#list>
		</table>
	</div>
</#if>

<@getDiscussion />

<#macro getAddChildPageIcon>
	<#if assetRenderer.hasEditPermission(themeDisplay.getPermissionChecker())>
		<#assign addPageURL = renderResponse.createRenderURL() />

		${addPageURL.setParameter("mvcRenderCommandName", "/wiki/edit_page")}
		${addPageURL.setParameter("redirect", currentURL)}
		${addPageURL.setParameter("nodeId", entry.getNodeId()?string)}
		${addPageURL.setParameter("title", "")}
		${addPageURL.setParameter("editTitle", "1")}
		${addPageURL.setParameter("parentTitle", entry.getTitle())}

		<@liferay_ui["icon"]
			icon="plus"
			label=true
			markupView="lexicon"
			message="add-child-page"
			url=addPageURL?string
		/>
	</#if>
</#macro>

<#macro getAttatchmentsIcon>
	<#assign viewPageAttachmentsURL = renderResponse.createRenderURL() />

	${viewPageAttachmentsURL.setParameter("mvcRenderCommandName", "/wiki/view_page_attachments") }

	<@liferay_ui["icon"]
		icon="paperclip"
		label=true
		markupView="lexicon"
		message=''${entry.getAttachmentsFileEntriesCount() + languageUtil.get(locale, "attachments")}''
		url=viewPageAttachmentsURL?string
	/>
</#macro>

<#macro getDiscussion>
	<#if validator.isNotNull(assetRenderer.getDiscussionPath()) && wikiPortletInstanceConfiguration.enableComments()>
		<br />

		<@liferay_comment["discussion"]
			className=wikiPageClassName
			classPK=entry.getResourcePrimKey()
			ratingsEnabled=wikiPortletInstanceConfiguration.enableCommentRatings()
			redirect=currentURL
			subject=assetRenderer.getTitle(locale)
			userId=assetRenderer.getUserId()
		/>
	</#if>
</#macro>

<#macro getEditIcon>
	<#if assetRenderer.hasEditPermission(themeDisplay.getPermissionChecker())>
		<#assign editPageURL = renderResponse.createRenderURL() />

		${editPageURL.setParameter("mvcRenderCommandName", "/wiki/edit_page")}
		${editPageURL.setParameter("redirect", currentURL)}
		${editPageURL.setParameter("nodeId", entry.getNodeId()?string)}
		${editPageURL.setParameter("title", entry.getTitle())}

		<@liferay_ui["icon"]
			icon="pencil"
			markupView="lexicon"
			message=entry.getTitle()
			url=editPageURL?string
		/>
	</#if>
</#macro>

<#macro getPageDetailsIcon>
	<#assign viewPageDetailsURL = renderResponse.createRenderURL() />

	${viewPageDetailsURL.setParameter("mvcRenderCommandName", "/wiki/view_page_details")}
	${viewPageDetailsURL.setParameter("redirect", currentURL)}

	<@liferay_ui["icon"]
		icon="document"
		markupView="lexicon"
		message="details"
		url=viewPageDetailsURL?string
	/>
</#macro>

<#macro getPrintIcon>
	<#assign printURL = renderResponse.createRenderURL() />

	${printURL.setParameter("viewMode", "print")}
	${printURL.setWindowState("pop_up")}

	<#assign
		title = languageUtil.format(locale, "print-x-x", ["hide-accessible", htmlUtil.escape(assetRenderer.getTitle(locale))], false)
		taglibPrintURL = "javascript:Liferay.Util.openWindow({dialog: {width: 960}, id:''" + renderResponse.getNamespace() + "printAsset'', title: ''" + title + "'', uri: ''" + htmlUtil.escapeURL(printURL.toString()) + "''});"
	/>

	<@liferay_ui["icon"]
		icon="print"
		markupView="lexicon"
		message="print"
		url=taglibPrintURL
	/>
</#macro>

<#macro getRatings
	cssClass
	entry
>
	<#if wikiPortletInstanceConfiguration.enablePageRatings()>
		<div class="${cssClass}">
			<@liferay_ui["ratings"]
				className=wikiPageClassName
				classPK=entry.getResourcePrimKey()
			/>
		</div>
	</#if>
</#macro>

<#macro getRelatedAssets>
	<#if assetEntry?? && wikiPortletInstanceConfiguration.enableRelatedAssets()>
		<@liferay_asset["asset-links"] assetEntryId=assetEntry.getEntryId() />
	</#if>
</#macro>', 0, 20106, NULL, CAST(N'2023-11-08T21:12:13.5870000' AS DateTime2))
GO
INSERT [dbo].[DDMTemplateVersion] ([mvccVersion], [templateVersionId], [groupId], [companyId], [userId], [userName], [createDate], [classNameId], [classPK], [templateId], [version], [name], [description], [language], [script], [status], [statusByUserId], [statusByUserName], [statusDate]) VALUES (0, 1814927, 20129, 20102, 20106, NULL, CAST(N'2023-11-08T21:12:13.6860000' AS DateTime2), 238001, 0, 285292, N'1.6', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Name language-id="en_US">Basic</Name></root>', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Description language-id="en_US">Displays titles, authors, and abstracts compactly for blog entries.</Description></root>', N'ftl', N'<div class="widget-mode-simple">
	<#if entries?has_content>
		<#list entries as curBlogEntry>
			<div class="widget-mode-simple-entry">
				<div class="autofit-row widget-topbar">
					<div class="autofit-col autofit-col-expand">
						<#assign viewEntryPortletURL = renderResponse.createRenderURL() />

						${viewEntryPortletURL.setParameter("mvcRenderCommandName", "/blogs/view_entry")}
						${viewEntryPortletURL.setParameter("redirect", currentURL)}

						<#if validator.isNotNull(curBlogEntry.getUrlTitle())>
							${viewEntryPortletURL.setParameter("urlTitle", curBlogEntry.getUrlTitle())}
						<#else>
							${viewEntryPortletURL.setParameter("entryId", curBlogEntry.getEntryId()?string)}
						</#if>

						<h3 class="title">
							<a class="title-link" href="${viewEntryPortletURL.toString()}">${htmlUtil.escape(blogsEntryUtil.getDisplayTitle(resourceBundle, curBlogEntry))}</a>
						</h3>
					</div>

					<div class="autofit-col visible-interaction">
						<div class="dropdown dropdown-action">
							<@liferay_ui["icon-menu"]
								direction="left-side"
								icon=""
								markupView="lexicon"
								message="actions"
								showWhenSingleIcon=true
							>
								<#if blogsEntryPermission.contains(permissionChecker, curBlogEntry, "UPDATE")>
									<#assign editEntryPortletURL = renderResponse.createRenderURL() />

									${editEntryPortletURL.setWindowState(windowStateFactory.getWindowState("MAXIMIZED"))}
									${editEntryPortletURL.setParameter("mvcRenderCommandName", "/blogs/edit_entry")}
									${editEntryPortletURL.setParameter("redirect", currentURL)}
									${editEntryPortletURL.setParameter("entryId", curBlogEntry.getEntryId()?string)}

									<@liferay_ui["icon"]
										label=true
										message="edit"
										url=editEntryPortletURL.toString()
									/>
								</#if>
								<#if blogsEntryPermission.contains(permissionChecker, curBlogEntry, "PERMISSIONS")>
									<#assign permissionsEntryURL = permissionsURLTag.doTag(null, "com.liferay.blogs.model.BlogsEntry", blogsEntryUtil.getDisplayTitle(resourceBundle, curBlogEntry), curBlogEntry.getGroupId()?string, curBlogEntry.getEntryId()?string, windowStateFactory.getWindowState("POP_UP").toString(), null, request) />

									<@liferay_ui["icon"]
										label=true
										message="permissions"
										method="get"
										url=permissionsEntryURL
										useDialog=true
									/>
								</#if>
								<#if blogsEntryPermission.contains(permissionChecker, curBlogEntry, "DELETE")>
									<#assign deleteEntryPortletURL = renderResponse.createActionURL() />

									${deleteEntryPortletURL.setParameter("javax.portlet.action", "/blogs/edit_entry")}
									${deleteEntryPortletURL.setParameter("cmd", trashHelper.isTrashEnabled(themeDisplay.getScopeGroupId())?then("move_to_trash", "delete"))}
									${deleteEntryPortletURL.setParameter("redirect", currentURL)}
									${deleteEntryPortletURL.setParameter("entryId", curBlogEntry.getEntryId()?string)}

									<@liferay_ui["icon-delete"]
										label=true
										trash=trashHelper.isTrashEnabled(themeDisplay.getScopeGroupId())
										url=deleteEntryPortletURL.toString()
									/>
								</#if>
							</@>
						</div>
					</div>
				</div>

				<div class="autofit-row widget-metadata">
					<div class="autofit-col inline-item-before">
						<@liferay_ui["user-portrait"]
							userId=curBlogEntry.userId
							userName=curBlogEntry.userName
						/>
					</div>

					<div class="autofit-col autofit-col-expand">
						<div class="autofit-row">
							<div class="autofit-col autofit-col-expand">
								<#if serviceLocator??>
									<#assign
										userLocalService = serviceLocator.findService("com.liferay.portal.kernel.service.UserLocalService")

										entryUser = userLocalService.fetchUser(curBlogEntry.getUserId())
									/>

									<#if entryUser?? && !entryUser.isDefaultUser()>
										<#assign entryUserURL = entryUser.getDisplayURL(themeDisplay) />
									</#if>
								</#if>

								<div class="text-truncate-inline">
									<a href="${(entryUserURL?? && validator.isNotNull(entryUserURL))?then(entryUserURL, "")}" class="text-truncate username">${curBlogEntry.getUserName()}</a>
								</div>

								<div>
									${dateUtil.getDate(curBlogEntry.getStatusDate(), "dd MMM", locale)}

									<#if blogsPortletInstanceConfiguration.enableReadingTime()>
										- <@liferay_reading_time["reading-time"] displayStyle="simple" model=curBlogEntry />
									</#if>

									<#if serviceLocator??>
										<#assign
											assetEntryLocalService = serviceLocator.findService("com.liferay.asset.kernel.service.AssetEntryLocalService")

											assetEntry = assetEntryLocalService.getEntry("com.liferay.blogs.model.BlogsEntry", curBlogEntry.getEntryId())
										/>

										<#if blogsPortletInstanceConfiguration.enableViewCount()>
											- <@liferay_ui["message"] arguments=assetEntry.getViewCount() key=(assetEntry.getViewCount()==0)?then("x-view", "x-views") />
										</#if>
									</#if>
								</div>
							</div>
						</div>
					</div>
				</div>

				<div class="widget-content">
					<p class="widget-resume">${stringUtil.shorten(htmlUtil.stripHtml(curBlogEntry.getContent()), 400)}</p>

					<div class="autofit-float autofit-row autofit-row-center widget-toolbar">
						<#if blogsPortletInstanceConfiguration.enableComments()>
							<div class="autofit-col">
								<#assign viewCommentsPortletURL = renderResponse.createRenderURL() />

								${viewCommentsPortletURL.setParameter("mvcRenderCommandName", "/blogs/view_entry")}
								${viewCommentsPortletURL.setParameter("scroll", renderResponse.getNamespace() + "discussionContainer")}

								<#if validator.isNotNull(curBlogEntry.getUrlTitle())>
									${viewCommentsPortletURL.setParameter("urlTitle", curBlogEntry.getUrlTitle())}
								<#else>
									${viewCommentsPortletURL.setParameter("entryId", curBlogEntry.getEntryId()?string)}
								</#if>

								<a class="btn btn-outline-borderless btn-outline-secondary btn-sm" href="${viewCommentsPortletURL.toString()}" title="${language.get(locale, "comments")}">
									<span class="inline-item inline-item-before">
										<@clay["icon"] symbol="comments" />
									</span> ${commentManager.getCommentsCount("com.liferay.blogs.model.BlogsEntry", curBlogEntry.getEntryId())}
								</a>
							</div>
						</#if>

						<#if blogsPortletInstanceConfiguration.enableRatings()>
							<div class="autofit-col">
								<@liferay_ui["ratings"]
									className="com.liferay.blogs.model.BlogsEntry"
									classPK=curBlogEntry.getEntryId()
								/>
							</div>
						</#if>

						<div class="autofit-col autofit-col-end">
							<#assign bookmarkURL = renderResponse.createRenderURL() />

							${bookmarkURL.setWindowState(windowStateFactory.getWindowState("NORMAL"))}
							${bookmarkURL.setParameter("mvcRenderCommandName", "/blogs/view_entry")}

							<#if validator.isNotNull(curBlogEntry.getUrlTitle())>
								${bookmarkURL.setParameter("urlTitle", curBlogEntry.getUrlTitle())}
							<#else>
								${bookmarkURL.setParameter("entryId", curBlogEntry.getEntryId()?string)}
							</#if>

							<@liferay_social_bookmarks["bookmarks"]
								className="com.liferay.blogs.model.BlogsEntry"
								classPK=curBlogEntry.getEntryId()
								displayStyle="inline"
								target="_blank"
								title=blogsEntryUtil.getDisplayTitle(resourceBundle, curBlogEntry)
								types=blogsPortletInstanceConfiguration.socialBookmarksTypes()
								url=portalUtil.getCanonicalURL(bookmarkURL.toString(), themeDisplay, themeDisplay.getLayout())
							/>
						</div>
					</div>
				</div>
			</div>
		</#list>
	</#if>
</div>', 0, 20106, NULL, CAST(N'2023-11-08T21:12:13.6860000' AS DateTime2))
GO
INSERT [dbo].[DDMTemplateVersion] ([mvccVersion], [templateVersionId], [groupId], [companyId], [userId], [userName], [createDate], [classNameId], [classPK], [templateId], [version], [name], [description], [language], [script], [status], [statusByUserId], [statusByUserName], [statusDate]) VALUES (0, 1814928, 20129, 20102, 20106, NULL, CAST(N'2023-11-08T21:12:13.7440000' AS DateTime2), 238001, 0, 285295, N'1.6', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Name language-id="en_US">Card</Name></root>', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Description language-id="en_US">Display cover images, titles, authors and abstracts using cards for blog entries.</Description></root>', N'ftl', N'<div class="row widget-mode-card">
	<#if entries?has_content>
		<#list entries as curBlogEntry>
			<#if curBlogEntry.getCoverImageURL(themeDisplay)??>
				<#assign cardImage = true />
			<#else>
				<#assign cardImage = false />
			</#if>

			<div class="col-lg-4">
				<div class="card">
					<#if cardImage>
						<div class="card-header">
							<div class="aspect-ratio aspect-ratio-8-to-3">
								<img alt="thumbnail" class="aspect-ratio-item-center-middle aspect-ratio-item-fluid" src="${curBlogEntry.getCoverImageURL(themeDisplay)}">
							</div>
						</div>
					</#if>

					<div class="card-body widget-topbar">
						<div class="autofit-row card-title">
							<div class="autofit-col autofit-col-expand">
								<#assign viewEntryPortletURL = renderResponse.createRenderURL() />

								${viewEntryPortletURL.setParameter("mvcRenderCommandName", "/blogs/view_entry")}
								${viewEntryPortletURL.setParameter("redirect", currentURL)}

								<#if validator.isNotNull(curBlogEntry.getUrlTitle())>
									${viewEntryPortletURL.setParameter("urlTitle", curBlogEntry.getUrlTitle())}
								<#else>
									${viewEntryPortletURL.setParameter("entryId", curBlogEntry.getEntryId()?string)}
								</#if>

								<h3 class="title">
									<a class="title-link" href="${viewEntryPortletURL.toString()}">
									${htmlUtil.escape(blogsEntryUtil.getDisplayTitle(resourceBundle, curBlogEntry))}</a>
								</h3>
							</div>

							<div class="autofit-col visible-interaction">
								<div class="dropdown dropdown-action">
									<@liferay_ui["icon-menu"]
										direction="left-side"
										icon=""
										markupView="lexicon"
										message="actions"
										showWhenSingleIcon=true
									>
										<#if blogsEntryPermission.contains(permissionChecker, curBlogEntry, "UPDATE")>
											<#assign editEntryPortletURL = renderResponse.createRenderURL() />

											${editEntryPortletURL.setWindowState(windowStateFactory.getWindowState("MAXIMIZED"))}
											${editEntryPortletURL.setParameter("mvcRenderCommandName", "/blogs/edit_entry")}
											${editEntryPortletURL.setParameter("redirect", currentURL)}
											${editEntryPortletURL.setParameter("entryId", curBlogEntry.getEntryId()?string)}

											<@liferay_ui["icon"]
												label=true
												message="edit"
												url=editEntryPortletURL.toString()
											/>
										</#if>
										<#if blogsEntryPermission.contains(permissionChecker, curBlogEntry, "PERMISSIONS")>
											<#assign permissionsEntryURL = permissionsURLTag.doTag(null, "com.liferay.blogs.model.BlogsEntry", blogsEntryUtil.getDisplayTitle(resourceBundle, curBlogEntry), curBlogEntry.getGroupId()?string, curBlogEntry.getEntryId()?string, windowStateFactory.getWindowState("POP_UP").toString(), null, request) />

											<@liferay_ui["icon"]
												label=true
												message="permissions"
												method="get"
												url=permissionsEntryURL
												useDialog=true
											/>
										</#if>
										<#if blogsEntryPermission.contains(permissionChecker, curBlogEntry, "DELETE")>
											<#assign deleteEntryPortletURL = renderResponse.createActionURL() />

											${deleteEntryPortletURL.setParameter("javax.portlet.action", "/blogs/edit_entry")}
											${deleteEntryPortletURL.setParameter("cmd", trashHelper.isTrashEnabled(themeDisplay.getScopeGroupId())?then("move_to_trash", "delete"))}
											${deleteEntryPortletURL.setParameter("redirect", currentURL)}
											${deleteEntryPortletURL.setParameter("entryId", curBlogEntry.getEntryId()?string)}

											<@liferay_ui["icon-delete"]
												label=true
												trash=trashHelper.isTrashEnabled(themeDisplay.getScopeGroupId())
												url=deleteEntryPortletURL.toString()
											/>
										</#if>
									</@>
								</div>
							</div>
						</div>

						<div class="autofit-row widget-metadata">
							<div class="autofit-col inline-item-before">
								<@liferay_ui["user-portrait"]
									size="lg"
									userId=curBlogEntry.userId
									userName=curBlogEntry.userName
								/>
							</div>

							<div class="autofit-col autofit-col-expand">
								<div class="autofit-row">
									<div class="autofit-col autofit-col-expand">
										<#if serviceLocator??>
											<#assign
												userLocalService = serviceLocator.findService("com.liferay.portal.kernel.service.UserLocalService")

												entryUser = userLocalService.fetchUser(curBlogEntry.getUserId())
											/>

											<#if entryUser?? && !entryUser.isDefaultUser()>
												<#assign entryUserURL = entryUser.getDisplayURL(themeDisplay) />
											</#if>
										</#if>

										<div class="text-truncate-inline">
											<a href="${(entryUserURL?? && validator.isNotNull(entryUserURL))?then(entryUserURL, "")}" class="text-truncate username">${curBlogEntry.getUserName()}</a>
										</div>

										<div>
											${dateUtil.getDate(curBlogEntry.getStatusDate(), "dd MMM", locale)}

											<#if blogsPortletInstanceConfiguration.enableReadingTime()>
												- <@liferay_reading_time["reading-time"] displayStyle="simple" model=curBlogEntry />
											</#if>

											<#if serviceLocator??>
												<#assign
													assetEntryLocalService = serviceLocator.findService("com.liferay.asset.kernel.service.AssetEntryLocalService")

													assetEntry = assetEntryLocalService.getEntry("com.liferay.blogs.model.BlogsEntry", curBlogEntry.getEntryId())
												/>

												<#if blogsPortletInstanceConfiguration.enableViewCount()>
													- <@liferay_ui["message"] arguments=assetEntry.getViewCount() key=(assetEntry.getViewCount()==0)?then("x-view", "x-views") />
												</#if>
											</#if>
										</div>
									</div>
								</div>
							</div>
						</div>

						<#if validator.isNotNull(curBlogEntry.getDescription())>
							<#assign content = curBlogEntry.getDescription() />
						<#else>
							<#assign content = curBlogEntry.getContent() />
						</#if>

						<#if cardImage>
							<p class="widget-resume">${stringUtil.shorten(htmlUtil.stripHtml(content), 150)}</p>
						<#else>
							<p class="widget-resume">${stringUtil.shorten(htmlUtil.stripHtml(content), 400)}</p>
						</#if>
					</div>

					<div class="card-footer">
						<div class="card-row">
							<div class="autofit-float autofit-row autofit-row-center widget-toolbar">
								<#if blogsPortletInstanceConfiguration.enableComments()>
									<div class="autofit-col">
										<#assign viewCommentsPortletURL = renderResponse.createRenderURL() />

										${viewCommentsPortletURL.setParameter("mvcRenderCommandName", "/blogs/view_entry")}
										${viewCommentsPortletURL.setParameter("scroll", renderResponse.getNamespace() + "discussionContainer")}

										<#if validator.isNotNull(curBlogEntry.getUrlTitle())>
											${viewCommentsPortletURL.setParameter("urlTitle", curBlogEntry.getUrlTitle())}
										<#else>
											${viewCommentsPortletURL.setParameter("entryId", curBlogEntry.getEntryId()?string)}
										</#if>

										<a class="btn btn-outline-borderless btn-outline-secondary btn-sm" href="${viewCommentsPortletURL.toString()}" title="${language.get(locale, "comments")}">
											<span class="inline-item inline-item-before">
												<@clay["icon"] symbol="comments" />
											</span> ${commentManager.getCommentsCount("com.liferay.blogs.model.BlogsEntry", curBlogEntry.getEntryId())}
										</a>
									</div>
								</#if>

								<#if blogsPortletInstanceConfiguration.enableRatings()>
									<div class="autofit-col">
										<@liferay_ui["ratings"]
											className="com.liferay.blogs.model.BlogsEntry"
											classPK=curBlogEntry.getEntryId()
										/>
									</div>
								</#if>

								<div class="autofit-col autofit-col-end">
									<#assign bookmarkURL = renderResponse.createRenderURL() />

									${bookmarkURL.setWindowState(windowStateFactory.getWindowState("NORMAL"))}
									${bookmarkURL.setParameter("mvcRenderCommandName", "/blogs/view_entry")}

									<#if validator.isNotNull(curBlogEntry.getUrlTitle())>
										${bookmarkURL.setParameter("urlTitle", curBlogEntry.getUrlTitle())}
									<#else>
										${bookmarkURL.setParameter("entryId", curBlogEntry.getEntryId()?string)}
									</#if>

									<@liferay_social_bookmarks["bookmarks"]
										className="com.liferay.blogs.model.BlogsEntry"
										classPK=curBlogEntry.getEntryId()
										maxInlineItems=0
										target="_blank"
										title=blogsEntryUtil.getDisplayTitle(resourceBundle, curBlogEntry)
										types=blogsPortletInstanceConfiguration.socialBookmarksTypes()
										url=portalUtil.getCanonicalURL(bookmarkURL.toString(), themeDisplay, themeDisplay.getLayout())
									/>
								</div>
							</div>
						</div>
					</div>
				</div>
			</div>
		</#list>
	</#if>
</div>', 0, 20106, NULL, CAST(N'2023-11-08T21:12:13.7440000' AS DateTime2))
