INSERT [dbo].[DDMTemplateVersion] ([mvccVersion], [templateVersionId], [groupId], [companyId], [userId], [userName], [createDate], [classNameId], [classPK], [templateId], [version], [name], [description], [language], [script], [status], [statusByUserId], [statusByUserName], [statusDate]) VALUES (0, 1820002, 20129, 20102, 20106, NULL, CAST(N'2023-12-05T21:43:08.8870000' AS DateTime2), 285215, 0, 285265, N'1.6', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Name language-id="en_US">Icon</Name></root>', N'<?xml version=''1.0'' encoding=''UTF-8''?><root available-locales="en_US" default-locale="en_US"><Description language-id="en_US">Displays the icon of the flag associated with each language.</Description></root>', N'ftl', N'<#if entries?has_content>
	<#list entries as entry>
		<#if entry.isSelected()>
