INSERT [dbo].[FragmentEntryLink] ([mvccVersion], [uuid_], [fragmentEntryLinkId], [groupId], [companyId], [userId], [userName], [createDate], [modifiedDate], [originalFragmentEntryLinkId], [fragmentEntryId], [classNameId], [classPK], [css], [html], [js], [configuration], [editableValues], [namespace], [position], [rendererKey], [lastPropagationDate], [lastPublishDate]) VALUES (0, N'42a76405-2e2a-945d-f3ce-e03609344f36', 292320, 292110, 20102, 20106, NULL, CAST(N'2021-03-25T19:54:04.1730000' AS DateTime2), CAST(N'2021-03-25T19:54:04.1730000' AS DateTime2), 0, 0, 20002, 39, N'', N'<div class="fragment">
	<div class="row info-section">
