INSERT [dbo].[FragmentEntryLink] ([mvccVersion], [uuid_], [fragmentEntryLinkId], [groupId], [companyId], [userId], [userName], [createDate], [modifiedDate], [originalFragmentEntryLinkId], [fragmentEntryId], [classNameId], [classPK], [css], [html], [js], [configuration], [editableValues], [namespace], [position], [rendererKey], [lastPropagationDate], [lastPublishDate]) VALUES (0, N'da81c815-baea-08e0-0301-a3c5e7daa394', 292376, 292110, 20102, 20106, NULL, CAST(N'2021-03-25T19:54:06.1870000' AS DateTime2), CAST(N'2021-03-25T19:54:06.1870000' AS DateTime2), 0, 0, 20002, 49, N'', N'<div class="fragment hero-section">
	<div class="d-none d-sm-flex row">
		<div class="col-lg-1"></div>
		<div class="col-lg-11 hero-breadcrumb">
			<lfr-widget-breadcrumb id="desktopTabletBreadcrumb">
			</lfr-widget-breadcrumb>
		</div>
	</div>
	<div class="hero-content row">
		<div class="col-lg-1"></div>
		<div class="col-lg-5">
			<div class="hero-breadcrumb mobile-only">
