	[/#if]
</div>', N'', N'{"fieldSets":[{"fields":[{"defaultValue":"true","dataType":"string","name":"calloutBox","typeOptions":{"validValues":[{"value":"true"},{"value":"false"}]},"label":"callout-box","type":"select"},{"defaultValue":"0","dataType":"string","name":"buttons","typeOptions":{"validValues":[{"value":"0"},{"value":"1"},{"value":"2"}]},"label":"buttons","type":"select"},{"defaultValue":"true","dataType":"string","name":"showSeparator","typeOptions":{"validValues":[{"value":"true"},{"value":"false"}]},"label":"show-separator","type":"select"}]}]}', N'{"com.liferay.fragment.entry.processor.background.image.BackgroundImageFragmentEntryProcessor":{},"com.liferay.fragment.entry.processor.editable.EditableFragmentEntryProcessor":{"benefits-description":{"defaultValue":"Employees can use their computers, tablets or smartphones to connect with providers via video conferencing for diagnosis and treatment of relatively minor injuries.","config":{}},"benefits-title":{"defaultValue":"<h2>Benefits<\/h2>","config":{}},"benefits-callout-text":{"defaultValue":"Contact your Church Mutual representative for more information or to schedule a demonstration.","config":{}}},"com.liferay.fragment.entry.processor.freemarker.FreeMarkerFragmentEntryProcessor":{}}', N'pygh', 0, NULL, CAST(N'2021-03-25T19:54:07.2370000' AS DateTime2), NULL)
