</div>', N'', N'{"fieldSets":[{"fields":[{"defaultValue":"true","dataType":"string","name":"calloutBox","typeOptions":{"validValues":[{"value":"true"},{"value":"false"}]},"label":"callout-box","type":"select"},{"defaultValue":"1","dataType":"string","name":"buttons","typeOptions":{"validValues":[{"value":"0"},{"value":"1"},{"value":"2"}]},"label":"buttons","type":"select"},{"defaultValue":"true","dataType":"string","name":"showSeparator","typeOptions":{"validValues":[{"value":"true"},{"value":"false"}]},"label":"show-separator","type":"select"}]}]}', N'{"com.liferay.fragment.entry.processor.background.image.BackgroundImageFragmentEntryProcessor":{},"com.liferay.fragment.entry.processor.editable.EditableFragmentEntryProcessor":{"benefits-description":{"defaultValue":"FREE 24/7 access to medical professionals who can help you appropriately manage work-related injuries.","config":{}},"benefits-btn-primary-help-text":{"defaultValue":"","config":{}},"benefits-btn-primary-link":{"defaultValue":"CALL (844) 322-4662","config":{"classPK":"","mapperType":"link","mappedField":"","href":"tel:(844) 322-4662","classNameId":"","fieldId":""}},"benefits-title":{"defaultValue":"<h2>Benefits<\/h2>","config":{}},"benefits-callout-text":{"defaultValue":"If a non-life-threatening injury occurs while you\u2019re on the job, get a fast and free advice by calling the 24/7 Nurse Hotline.","config":{}}},"com.liferay.fragment.entry.processor.freemarker.FreeMarkerFragmentEntryProcessor":{}}', N'ovsb', 0, NULL, CAST(N'2024-06-17T19:08:59.4490000' AS DateTime2), NULL)
