INSERT [dbo].[FragmentEntryLink] ([mvccVersion], [uuid_], [fragmentEntryLinkId], [groupId], [companyId], [userId], [userName], [createDate], [modifiedDate], [originalFragmentEntryLinkId], [fragmentEntryId], [classNameId], [classPK], [css], [html], [js], [configuration], [editableValues], [namespace], [position], [rendererKey], [lastPropagationDate], [lastPublishDate]) VALUES (0, N'1c13e56c-efb5-a4cc-08d3-22c253bc5cbd', 2650523, 292110, 20102, 20106, NULL, CAST(N'2024-06-17T19:08:59.4540000' AS DateTime2), CAST(N'2024-06-17T19:08:59.4540000' AS DateTime2), 0, 0, 20002, 44, N'', N'<div class="fragment">
