				<iframe class="hero-image-iframe hero-image-iframe-shadow" src="${configuration.sourceVideo}"></iframe>
			[#else]
				<img alt="image" src=${configuration.imageSrc} />
				<img class="hero-image-shadow" alt="image" src=${configuration.imageSrc} />
