INSERT [dbo].[Marketplace_App] ([uuid_], [appId], [companyId], [userId], [userName], [createDate], [modifiedDate], [remoteAppId], [title], [description], [category], [iconURL], [version], [required]) VALUES (N'e06b83c3-8588-03df-90d8-80de356443bc', 284115, 0, 0, NULL, CAST(N'2023-12-06T14:42:52.0680000' AS DateTime2), CAST(N'2023-12-06T14:42:52.0680000' AS DateTime2), 54369726, N'Liferay Screens Compatibility', N'This plugin is a portlet that exposes additional classes and methods that are not present in Liferay''s out-of-the-box API. These additional classes and methods allow Liferay Screens to do certain operations that are needed for the screenlets to work correctly.Please report issues with the Liferay Screens Compatibility Plugin by creating a ticket in https://issues.liferay.com/browse/LMW.Liferay Screens Compatibility 1.x is a Lab application and is not supported by Liferay.In Liferay 7.1, this app is installed by default and updated through Liferay DXP Fix Packs and Liferay Portal CE GA releases. Using Liferay Marketplace to update the app on Liferay 7.1 will cause an error.', N'Utility', N'https://web.liferay.com/web/guest/marketplace/-/mp/asset/icon/54369726/5.0.10', N'5.0.10', 0)
GO
